// The M4 benchmark harness (docs/design/MEMORY_STORE.md, "M4 -- benchmarks
// and the scale guard"): given a fixture generated by mcp/bench/fixture.ts,
// measures cold full index, warm refresh after touching k files, one recall
// query, and one graph query, on whichever StoreBackend is forced -- plus
// on-disk store size and a coarse in-process RSS sample. No network, no new
// dependency; only node:fs/node:path plus the real kernel.ts entry points a
// user's `kage index`/`kage refresh`/recall/graph-query calls already go
// through, so these numbers describe what a user actually experiences, not
// a synthetic microbenchmark of the store alone.
//
// mcp/bench/run.ts is the CLI entry point that drives this at real (1,000 /
// 10,000-file) scale and prints JSON for docs/BENCHMARKS.md; this file's
// own automated coverage is mcp/scale-guard.test.ts, which only exercises
// it at 200 files so the suite stays fast.

import { existsSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

import { indexProject, queryStructuralGraphFromStore, recall, refreshProject } from "../kernel.js";
import { writeManifest, type StoreManifest } from "../store/manifest.js";
import { sqliteStorePath } from "../store/sqlite.js";
import type { BackendKind } from "../store/types.js";
import { generateFixture, touchFiles, type FixtureOptions, type FixtureResult } from "./fixture.js";

/** Forces `dir`'s store manifest to `kind` before the first openStore() call -- same technique mcp/store-graph.test.ts's forceBackend() uses. */
export function forceBackend(dir: string, kind: BackendKind): void {
  const manifest: StoreManifest = { schema_version: 1, active_backend: kind, forced_backend: kind, counts: {}, last_rebuild_at: null };
  writeManifest(dir, manifest);
}

/** Recursively sums file sizes under `dir`. Returns { files: 0, bytes: 0 } for a missing directory (a legitimate "this backend wrote nothing yet" state). */
function dirSizeBytes(dir: string): { files: number; bytes: number } {
  if (!existsSync(dir)) return { files: 0, bytes: 0 };
  let files = 0;
  let bytes = 0;
  const stack = [dir];
  while (stack.length) {
    const current = stack.pop() as string;
    let entries: string[];
    try {
      entries = readdirSync(current);
    } catch {
      continue;
    }
    for (const entry of entries) {
      const full = join(current, entry);
      const stat = statSync(full);
      if (stat.isDirectory()) stack.push(full);
      else {
        files += 1;
        bytes += stat.size;
      }
    }
  }
  return { files, bytes };
}

/**
 * On-disk size of the derived store, backend-appropriate: the single
 * .sqlite file for the sqlite backend, or the whole structural/graph/
 * indexes tree the JSON backend owns. Mirrors mcp/cli.ts's `kage store
 * status` sizing intent but is computed independently here (this harness's
 * files are the only ones this run is scoped to touch).
 */
function storeSizeBytes(projectDir: string, backend: BackendKind): { files: number; bytes: number } {
  if (backend === "sqlite") {
    const path = sqliteStorePath(projectDir);
    if (!existsSync(path)) return { files: 0, bytes: 0 };
    const stat = statSync(path);
    return { files: 1, bytes: stat.size };
  }
  const structural = dirSizeBytes(join(projectDir, ".agent_memory", "structural"));
  const indexes = dirSizeBytes(join(projectDir, ".agent_memory", "indexes"));
  const graph = dirSizeBytes(join(projectDir, ".agent_memory", "graph"));
  return {
    files: structural.files + indexes.files + graph.files,
    bytes: structural.bytes + indexes.bytes + graph.bytes,
  };
}

export interface BenchMeasurement {
  backend: BackendKind;
  fileCount: number;
  packetCount: number;
  touchedFileCount: number;
  coldIndexMs: number;
  warmRefreshMs: number;
  recallMs: number;
  recallHitCount: number;
  graphQueryMs: number;
  graphQueryFileHits: number;
  graphQuerySymbolHits: number;
  storeOnDiskFiles: number;
  storeOnDiskBytes: number;
  rssBeforeBytes: number;
  rssAfterColdIndexBytes: number;
}

export interface RunBenchmarkOptions extends FixtureOptions {
  backend: BackendKind;
  /** Files to touch before the warm-refresh measurement. Default: max(1, 1% of fileCount). */
  touchCount?: number;
}

/**
 * Generates a fresh fixture inside `dir` (must be empty), forces `backend`,
 * then runs the cold-index / warm-refresh / recall / graph-query
 * measurements against the SAME real kernel.ts entry points `kage index`,
 * `kage refresh`, recall, and queryStructuralGraphFromStore use. `dir` is
 * left populated on return -- the caller owns cleanup (mcp/bench/run.ts
 * removes its own temp dirs; mcp/scale-guard.test.ts's fixtures live under
 * node:os tmpdir() and are cleaned up the same way every other test file's
 * tempProject() helper is).
 */
export function runBenchmark(dir: string, opts: RunBenchmarkOptions): BenchMeasurement {
  const fixture: FixtureResult = generateFixture(dir, opts);
  forceBackend(dir, opts.backend);

  const rssBeforeBytes = process.memoryUsage().rss;
  const coldStart = process.hrtime.bigint();
  indexProject(dir);
  const coldIndexMs = Number(process.hrtime.bigint() - coldStart) / 1e6;
  const rssAfterColdIndexBytes = process.memoryUsage().rss;

  const recallStart = process.hrtime.bigint();
  const recallResult = recall(dir, fixture.recallTerm, 5);
  const recallMs = Number(process.hrtime.bigint() - recallStart) / 1e6;

  const graphStart = process.hrtime.bigint();
  const graphResult = queryStructuralGraphFromStore(dir, fixture.graphTerm, 10);
  const graphQueryMs = Number(process.hrtime.bigint() - graphStart) / 1e6;

  const touchCount = opts.touchCount ?? Math.max(1, Math.round(opts.fileCount * 0.01));
  const touched = touchFiles(fixture, opts.seed, touchCount);

  const warmStart = process.hrtime.bigint();
  refreshProject(dir);
  const warmRefreshMs = Number(process.hrtime.bigint() - warmStart) / 1e6;

  const store = storeSizeBytes(dir, opts.backend);

  return {
    backend: opts.backend,
    fileCount: opts.fileCount,
    packetCount: opts.packetCount,
    touchedFileCount: touched.length,
    coldIndexMs,
    warmRefreshMs,
    recallMs,
    recallHitCount: recallResult.results.length,
    graphQueryMs,
    graphQueryFileHits: graphResult.files.length,
    graphQuerySymbolHits: graphResult.symbols.length,
    storeOnDiskFiles: store.files,
    storeOnDiskBytes: store.bytes,
    rssBeforeBytes,
    rssAfterColdIndexBytes,
  };
}

export { generateFixture, fixtureFingerprint, touchFiles, queryTermFor, graphTermFor } from "./fixture.js";
export type { FixtureOptions, FixtureResult } from "./fixture.js";
